/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"sounddesign-level-16","number":16,"title":"Parameter Encyclopedia","skillBand":"Textbook","duration":"From the course textbook","summary":"An Oscillator (Signal Generator) is the periodic or stochastic sound source in a synthesizer. This volume details every discrete parameter found in modern analog, virtual-analog, wavetable, additive, phase-modulation, and physical modeling ","modules":[{"id":"sounddesign-m-1-1-2","code":"1","title":"Comprehensive Parameter Encyclopedia — Volume 1: Oscillators & Signal Generators","blurb":"An Oscillator (Signal Generator) is the periodic or stochastic sound source in a synthesizer. This volume details every discrete parameter found in modern analog, virtual-analog, wavetable, additive, phase-modulation, and physical modeling ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-01-oscillator-generator-parameters","title":"# Comprehensive Parameter Encyclopedia — Volume 1: Oscillators & Signal Generators","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"An <strong>Oscillator (Signal Generator)</strong> is the periodic or stochastic sound source in a synthesizer. This volume details every discrete parameter found in modern analog, virtual-analog, wavetable, additive, phase-modulation, and physical modeling oscillators without raw mathematical equations."}]},{"type":"step","title":"1. Pitch & Frequency Parameters","blocks":[{"type":"heading","text":"1.1 Octave (Oct / Coarse Octave)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Transposes the oscillator fundamental pitch in octave jumps (doubling or halving the frequency per step).","<strong>Value Range:</strong> Typically -3, -2, -1, 0, +1, +2, +3 (or labeled in classic organ footage: 32', 16', 8', 4', 2').","<strong>Audible Effect:</strong> ","<strong>Negative values (-1, -2 / 16', 32'):</strong> Shifts the oscillator down into deep bass and sub-bass registers.","<strong>Value 0 (8'):</strong> Standard concert pitch reference (middle register).","<strong>Positive values (+1, +2 / 4', 2'):</strong> Shifts the oscillator up into lead, bell, and high-frequency registers.","<strong>Interactions:</strong> Works in combination with Semitone and Fine Tune settings."],"ordered":false},{"type":"heading","text":"1.2 Semitone (Semi / Coarse Tune)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Transposes the oscillator pitch in standard musical half-step increments across the 12-tone keyboard scale.","<strong>Value Range:</strong> Typically -12 to +12 semitones (or up to +/- 24 semitones).","<strong>Acoustic &amp; Musical Roles:</strong>","<strong>+7 Semitones (Perfect Fifth):</strong> Adds harmonic thickness, chord weight, and classic techno/house chord stab intervals.","<strong>+4 Semitones (Major Third) / +3 Semitones (Minor Third):</strong> Builds fixed chord triads inside a multi-oscillator patch.","<strong>+12 Semitones (Octave):</strong> Shifts pitch up by one full octave.","<strong>+1 to +2 Semitones (Dissonant Seconds):</strong> Creates extreme clashing, tension, and alarm/siren effects."],"ordered":false},{"type":"heading","text":"1.3 Fine Tune (Cents / Detune)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Adjusts pitch in micro-fractions of a semitone (1 semitone = 100 cents).","<strong>Value Range:</strong> Typically -50 to +50 cents (or -100 to +100 cents).","<strong>Acoustic &amp; Musical Roles:</strong>","<strong>0 Cents:</strong> Exact pitch alignment.","<strong>+/- 3 to +/- 8 Cents:</strong> Subtle analog warmth, natural movement, and organic thickening.","<strong>+/- 10 to +/- 20 Cents:</strong> The classic Drum &amp; Bass <strong>Reese Bass</strong> phase-beating effect (slow rolling movement).","<strong>+/- 25 to +/- 40 Cents:</strong> Wide supersaw detuning for energetic trance and future bass leads. Beyond 40 cents, the sound begins to lose its clear musical pitch center."],"ordered":false},{"type":"heading","text":"1.4 Fixed Frequency Mode (Hz / Frequency)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Decouples the oscillator from incoming MIDI note keys, forcing it to cycle at a constant, static frequency in Hertz (Hz) or Kilohertz (kHz).","<strong>Value Range:</strong> Typically 1 Hz to 20,000 Hz.","<strong>Acoustic &amp; Musical Roles:</strong>","<strong>Percussion Synthesis:</strong> Ensures that beater clicks (e.g. 1.4 kHz) or snare body tones (e.g. 180 Hz) remain identical in pitch no matter which key triggers the sound.","<strong>Formant Simulation:</strong> Fixed-frequency modulators in FM synthesis create static vocal tract vowel resonances.","<strong>LFO Conversion:</strong> Setting fixed frequency to low values (0.1 to 10 Hz) turns the audio oscillator into a modulation utility."],"ordered":false},{"type":"heading","text":"1.5 FM Coarse Ratio (Carrier-to-Modulator Multiplier)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> In Phase Modulation and FM engines (such as Ableton Operator), sets the modulator oscillator frequency as a direct multiplier of the fundamental note pitch.","<strong>Value Range:</strong> 0.5, 1.0, 2.0, 3.0, 4.0, up to 20.0 (or continuous decimals).","<strong>Harmonic Interval &amp; Timbral Consequences:</strong>","<strong>Ratio 0.5 (Subharmonic):</strong> Adds a deep subharmonic octave beneath the fundamental.","<strong>Ratio 1.0 (Unison 1:1):</strong> Generates all natural integer harmonics, producing rich sawtooth-like brass and basses.","<strong>Ratio 2.0 (Octave 1:2):</strong> Emphasizes odd harmonics, producing hollow square-wave plucks and classic deep house basses (Donk).","<strong>Ratio 3.0 (1:3 Octave + Fifth):</strong> Produces nasal, reed-like, hollow tones and metallic leads.","<strong>Ratio 4.0 (1:4 Two Octaves):</strong> Crystalline electric piano bells, Rhodes tines, and glass chimes.","<strong>Decimal Ratios (e.g. 1.414, 2.73):</strong> Generates complex, non-harmonic overtones, synthesizing bells, metallic cowbells, cymbals, and industrial clangs."],"ordered":false}]},{"type":"step","title":"2. Waveform & Geometric Parameters","blocks":[{"type":"heading","text":"2.1 Waveform Selector (Shape)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Selects the foundational waveform shape generated by the oscillator.","<strong>Core Classical Shapes:</strong>","<strong>Sine:</strong> Pure fundamental tone only. Zero upper overtones. Highest energy concentration per frequency band.","<strong>Triangle:</strong> Odd harmonics only, with high harmonics dropping off very quickly. Smooth, warm, woody.","<strong>Square:</strong> Odd harmonics only, with high harmonics dropping off gradually. Hollow, reedy, aggressive.","<strong>Sawtooth:</strong> All harmonics (both even and odd), creating a rich, full-frequency buzz. The universal starting point for subtractive synthesis."],"ordered":false},{"type":"heading","text":"2.2 Pulse Width (PW)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Adjusts the balance of time a square wave spends high versus low across each cycle (the duty cycle).","<strong>Value Range:</strong> 1% to 99% (with 50% being a standard, symmetrical Square wave).","<strong>Acoustic Consequences:</strong>","At 50%: Only odd harmonics exist (hollow, woody tone).","Away from 50% (e.g. 25% or 10%): Even harmonics enter the sound, making it brighter and more nasal.","Extreme values (5% or 95%): Thin, reedy, cutting, oboe-like tone."],"ordered":false},{"type":"heading","text":"2.3 Pulse Width Modulation (PWM / PWM Depth)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Continuously sweeping the Pulse Width back and forth using an LFO or envelope.","<strong>Acoustic Result:</strong> Creates a rich, chorus-like moving texture without altering the underlying musical note pitch. The signature sound of classic analog string machines and Juno pads."],"ordered":false},{"type":"heading","text":"2.4 Phase Offset & Phase Retrigger (Phase / Sync Phase)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Sets the exact starting point of the waveform cycle when a key is struck.","<strong>Modes:</strong>","<strong>Retrigger ON (Hard Phase Lock):</strong> The waveform resets to the exact same starting point on every note strike.","<em>Role:</em> Essential for electronic kick drums and sub-basses to guarantee identical punch on every hit with zero phase cancellation.","<strong>Retrigger OFF / Free-Run (Random Phase):</strong> The waveform starts at random angles on each strike.","<em>Role:</em> Essential for pads, chord stacks, and supersaws to prevent harsh flanging clicks when hitting chords."],"ordered":false},{"type":"heading","text":"2.5 Hard Sync (Oscillator Sync)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Forces a slave oscillator to restart its waveform cycle whenever a master oscillator completes one full period.","<strong>Audible Effect:</strong> Sweeping the slave oscillator pitch upward produces screaming, tearing, metallic laser sweeps while the played musical note pitch remains locked to the master keyboard."],"ordered":false}]},{"type":"step","title":"3. Unison & Voice Spreading Parameters","blocks":[{"type":"heading","text":"3.1 Unison Voice Count (Unison / Voices)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Multiplies the active oscillator into multiple identical copies for each note played (2, 4, 8, 12, 16 voices).","<strong>Acoustic Role:</strong> Multiplies sound density, turning single oscillators into massive walls of sound."],"ordered":false},{"type":"heading","text":"3.2 Unison Detune (Spread / Detune Depth)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Offsets the pitch of the cloned unison copies slightly sharp and flat relative to the center note.","<strong>Acoustic Result:</strong> Multiple detuned copies generate rich phase beating, transforming a simple saw into a massive festival <strong>Supersaw</strong>."],"ordered":false},{"type":"heading","text":"3.3 Unison Stereo Spread (Width)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Spreads the detuned unison copies across the stereo field from left to right.","<strong>Acoustic Role:</strong> Creates a wide, room-filling stereo soundstage."],"ordered":false},{"type":"heading","text":"3.4 Unison Blend / Center Volume","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Balances the volume between the in-tune center voice and the detuned outer stereo voices.","<strong>Acoustic Role:</strong> Keeps a solid, focused note center in the middle of the mix while outer voices provide wide stereo thickness."],"ordered":false}]},{"type":"step","title":"4. Wavetable & Spectral Parameters","blocks":[{"type":"heading","text":"4.1 Wavetable Position (Wave Frame / WT Pos)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Selects which waveform frame in the wavetable sequence is currently playing.","<strong>Audible Effect:</strong> Sweeping wavetable position using envelopes or LFOs smoothly morphs the sound from one timbre into another over time (e.g. from smooth analog warmth into aggressive digital metal)."],"ordered":false},{"type":"heading","text":"4.2 Frame Interpolation (Morph Mode)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The method used to smooth the sound when resting between two stored frames.","<strong>Modes:</strong>","<strong>None / Off:</strong> Steps abruptly between frames, creating 8-bit digital crunch and lo-fi zipper noise.","<strong>Linear / Waveform:</strong> Smoothly blends adjacent frames. Ideal for natural analog waveforms.","<strong>Spectral Morph:</strong> Smooths harmonic overtones independently. Ideal for vocal formants and morphing digital textures."],"ordered":false},{"type":"heading","text":"4.3 Spectral Warping Modes (Warp / Modifier)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Real-time transformations applied directly to the oscillator waveform before it reaches the filter.","<strong>Core Modes:</strong>","<strong>Formant Scale:</strong> Shifts harmonic spacing to impart vocal vowels (A, E, I, O, U) into any sound.","<strong>Harmonic Stretch:</strong> Compresses or expands overtones to create modern metallic bass growls.","<strong>Inharmonic Smear:</strong> Blurs harmonic lines into glassy, gong-like chimes and metallic textures.","<strong>Sync (Windowed Hard Sync):</strong> Squeezes cycles together for aggressive sync sweeps.","<strong>Bend / Squeeze:</strong> Pinches waveform shapes for hollow, woody timbres."],"ordered":false}]},{"type":"step","title":"5. Noise & Specialty Generators","blocks":[{"type":"heading","text":"5.1 Noise Color / Distribution","level":3},{"type":"list","items":["<strong>White Noise:</strong> Equal energy across all frequencies. Bright, sizzling, sharp (hi-hats, sweeps).","<strong>Pink Noise:</strong> Balanced natural frequency distribution. Warm, balanced roar (rain, wind, snare bodies).","<strong>Brownian (Red) Noise:</strong> Heavy low-frequency emphasis. Deep rumble, thunder, waterfall roar."],"ordered":false},{"type":"heading","text":"5.2 Sample-and-Hold Noise (S&H / Jitter)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Clocks random stepped voltages at a controllable speed, creating stepped retro computer blips or tuned noise textures."],"ordered":false},{"type":"heading","text":"5.3 Sub-Oscillator","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> A dedicated auxiliary oscillator locked 1 or 2 octaves below Oscillator 1.","<strong>Sound Design Role:</strong> Provides a solid, clean low-end foundation beneath complex or high-passed mid-range leads and growls."],"ordered":false}]}],"minutes":10}],"exercises":[]},{"id":"sounddesign-m-2-2-3","code":"2","title":"Comprehensive Parameter Encyclopedia — Volume 2: Filters & Subtractive Parameters","blurb":"A Filter (VCF / Digital Biquad) is a frequency-dependent volume control circuit. This volume details every discrete parameter found in subtractive filters, explaining how frequencies are cut, boosted, shaped, and routed without raw equation","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-02-filter-subtractive-parameters","title":"# Comprehensive Parameter Encyclopedia — Volume 2: Filters & Subtractive Parameters","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"A <strong>Filter (VCF / Digital Biquad)</strong> is a frequency-dependent volume control circuit. This volume details every discrete parameter found in subtractive filters, explaining how frequencies are cut, boosted, shaped, and routed without raw equations."}]},{"type":"step","title":"1. Primary Filter Coordinates","blocks":[{"type":"heading","text":"1.1 Cutoff Frequency (Cutoff / Frequency / fc)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The frequency point where the filter transitions from passing audio untouched (Passband) to cutting audio (Stopband).","<strong>The -3 dB Standard:</strong> By audio engineering standard, the cutoff point is the exact frequency where volume has dropped by 3 dB.","<strong>Logarithmic Scaling:</strong> The cutoff knob moves in musical octaves rather than linear numbers, matching how human ears perceive pitch.","<strong>Audible Effect:</strong>","<strong>Low-Pass Filter:</strong> Turning clockwise opens the filter, letting in higher overtones and increasing brightness. Turning counter-clockwise darkens the sound until only deep sub-bass remains.","<strong>High-Pass Filter:</strong> Turning clockwise cuts out low bass, thinning the sound and leaving only crisp highs."],"ordered":false},{"type":"heading","text":"1.2 Resonance (Q / Peak / Emphasis / Feedback)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Boosting the volume of frequencies right at the Cutoff point by feeding a portion of the filter output back into its input.","<strong>Acoustic Behavior Across Values:</strong>","<strong>Low Resonance:</strong> Flat, clean, transparent frequency cutoff.","<strong>Medium Resonance:</strong> Adds a focused vocal quality, hollow nasal pinch, and extra presence.","<strong>High Resonance:</strong> Emphasizes specific overtones with a sharp, singing whistle.","<strong>Self-Oscillation (Max Resonance):</strong> The filter feeds back so intensely that it turns into a pure sine wave oscillator at the cutoff frequency, making sound even when oscillators are silent."],"ordered":false},{"type":"heading","text":"1.3 Slope / Poles (dB/Octave / Rolloff Steepness)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> How aggressively the filter cuts volume past the cutoff frequency, measured in decibels per octave (dB/octave).","<strong>The Pole Rule:</strong> In analog hardware, each filter circuit stage (pole) adds 6 dB of rolloff per octave.","<strong>Standard Configurations:</strong>","<strong>6 dB/octave (1-Pole):</strong> Very gentle, transparent, natural rolloff.","<strong>12 dB/octave (2-Pole):</strong> Warm and musical, classic Oberheim style. Retains good brightness.","<strong>18 dB/octave (3-Pole):</strong> Aggressive, squelchy acid bite (Roland TB-303 and Korg MS-20 style).","<strong>24 dB/octave (4-Pole):</strong> Steep, fat, authoritative analog wall (Classic Moog ladder style).","<strong>48 dB/octave (8-Pole):</strong> Surgical digital brick-wall cut."],"ordered":false}]},{"type":"step","title":"2. Filter Topologies & Circuit Models","blocks":[{"type":"heading","text":"2.1 Low-Pass Filter (LPF)","level":3},{"type":"list","items":["<strong>Acoustic Function:</strong> Passes all low frequencies below the cutoff and cuts high frequencies above it.","<strong>Sound Design Role:</strong> The universal workhorse for making warm basses, plucks, brass, and pads."],"ordered":false},{"type":"heading","text":"2.2 High-Pass Filter (HPF)","level":3},{"type":"list","items":["<strong>Acoustic Function:</strong> Passes all high frequencies above the cutoff and cuts low frequencies below it.","<strong>Sound Design Role:</strong> Cleaning out low-end rumble (below 30 Hz), making room for kick drums, and isolating airy textures."],"ordered":false},{"type":"heading","text":"2.3 Band-Pass Filter (BPF)","level":3},{"type":"list","items":["<strong>Acoustic Function:</strong> Cuts both lows and highs, allowing only a focused middle frequency band through.","<strong>Sound Design Role:</strong> Creating telephone vocal effects, wah-wah sweeps, and resonant lead sounds."],"ordered":false},{"type":"heading","text":"2.4 Notch Filter (Band-Reject)","level":3},{"type":"list","items":["<strong>Acoustic Function:</strong> The opposite of Band-Pass. Passes all lows and highs while carving a sharp silence notch in the middle.","<strong>Sound Design Role:</strong> Sweeping notches across detuned saw waves creates the moving phasing effect of <strong>Neurofunk Reese Basslines</strong>."],"ordered":false},{"type":"heading","text":"2.5 Comb Filter","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Uses a very short delay line with feedback to create an array of harmonic resonant peaks and dips.","<strong>Sound Design Role:</strong> Creating metallic flanging, robotic vocal textures, and plucked string/pipe sounds (physical modeling)."],"ordered":false},{"type":"heading","text":"2.6 Formant / Vowel Filter","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Pairs multiple resonant bandpass peaks together to mimic the human vocal tract vowels (A, E, I, O, U).","<strong>Sound Design Role:</strong> Turning standard synthesizer waves into talking dubstep growls and vowel sounds."],"ordered":false},{"type":"heading","text":"2.7 Circuit Modeling Profiles","level":3},{"type":"list","items":["<strong>Ladder (Moog Style):</strong> Saturated, warm, fat low-end. High resonance slightly lowers bass passband volume.","<strong>K35 / MS-20 Style:</strong> Aggressive, screaming, dirty resonance with non-linear distortion.","<strong>State-Variable (SEM Style):</strong> Smooth and musical; preserves low-end punch even at high resonance.","<strong>Diode (TB-303 Style):</strong> Rubbery, asymmetric clipping squelch."],"ordered":false}]},{"type":"step","title":"3. Filter Modulation & Control Parameters","blocks":[{"type":"heading","text":"3.1 Keytracking (Key Follow)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Moves the Cutoff Frequency up and down in response to the keyboard notes being played.","<strong>Settings:</strong>","<strong>0% (Off):</strong> Cutoff stays fixed. Higher notes on the keyboard sound progressively darker.","<strong>100% (Full Tracking):</strong> Cutoff tracks keyboard notes in exact musical unison, maintaining identical brightness across all octaves."],"ordered":false},{"type":"heading","text":"3.2 Filter Envelope Amount (Env Depth)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Sets how far the Filter Envelope sweeps the Cutoff Frequency upon striking a note.","<strong>Polarity:</strong>","<strong>Positive (+):</strong> Sweeps cutoff upward on attack and drops it on decay (Plucks, Brass).","<strong>Negative (- / Inverted):</strong> Pulls cutoff downward on attack, creating sucking reverse effects."],"ordered":false},{"type":"heading","text":"3.3 Filter Drive (Pre- vs. Post-Filter Saturation)","level":3},{"type":"list","items":["<strong>Pre-Filter Drive:</strong> Distorts the raw sound <em>before</em> the filter, adding overtones that the filter then sculpts.","<strong>Post-Filter Drive:</strong> Distorts the signal <em>after</em> the filter, saturating the resonant peak into a thick analog growl."],"ordered":false},{"type":"heading","text":"3.4 Filter Morph / Style Blend","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Smoothly transitions the filter shape from Low-Pass to Band-Pass to High-Pass using a single control knob."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-3-3-2","code":"3","title":"Comprehensive Parameter Encyclopedia — Volume 3: Envelopes & Dynamics","blurb":"An Envelope Generator (EG) outputs a dynamic control signal triggered by MIDI note-on and note-off events. This volume details every discrete parameter found in envelope sections, contrasting time stages versus level coordinates, response c","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-03-envelope-dynamics-parameters","title":"# Comprehensive Parameter Encyclopedia — Volume 3: Envelopes & Dynamics","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"An <strong>Envelope Generator (EG)</strong> outputs a dynamic control signal triggered by MIDI note-on and note-off events. This volume details every discrete parameter found in envelope sections, contrasting time stages versus level coordinates, response curves, and performance scaling."}]},{"type":"step","title":"1. Classical ADSR Parameters","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Level\n100% |      /\\ (Attack Peak)\n     |     /  \\\n     |    /    \\======================== (Sustain Level: HELD AS LONG AS KEY IS PRESSED)\n     |   /      \\ (Decay Stage)         \\\n  0% +--+--------+-----------------------+---------&gt; Time\n       [A]      [D]                     [R] (Release Stage after releasing key)</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                     THE ADSR COORDINATE MATRIX                                    |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| ENVELOPE STAGE    | METRIC UNIT                 | CATEGORY              | FUNCTION                |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **Attack (A)**    | **Time** (Milliseconds / Sec)| **Time Duration**     | Duration to reach peak. |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **Decay (D)**     | **Time** (Milliseconds / Sec)| **Time Duration**     | Duration to drop to Sust|\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **Sustain (S)**   | **Level** (dB / 0-100%)     | **AMPLITUDE LEVEL**   | Level held while keyed. |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **Release (R)**   | **Time** (Milliseconds / Sec)| **Time Duration**     | Duration to drop to 0.  |\n+-------------------+-----------------------------+-----------------------+-------------------------+</pre>"},{"type":"heading","text":"1.1 Attack Time (Attack / Att)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The duration of time required for the envelope to rise from zero to its maximum peak upon striking a key.","<strong>Value Range:</strong> 0.0 ms to 20.0 seconds.","<strong>Sound Design Roles:</strong>","<strong>0 ms to 2 ms (Instantaneous):</strong> Essential for percussive clicks, kicks, basslines, and plucks.","<strong>5 ms to 20 ms (Soft Transient):</strong> Smooths out digital clicks while retaining punch (Brass, Organs).","<strong>50 ms to 300 ms (Swell / Bowed):</strong> Simulates bowed strings (Violin, Cello) and slow brass swells.","<strong>1.0 s to 5.0 s (Atmospheric Fade):</strong> Ambient pads, drone soundscapes, evolving cinematic layers."],"ordered":false},{"type":"heading","text":"1.2 Attack Curve / Shape (Tension / Slope)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The curvature of the rise from zero to peak.","<strong>Topologies:</strong>","<strong>Linear:</strong> Constant straight rise.","<strong>Exponential:</strong> Rises rapidly at first, then settles into peak. Snappy and immediate.","<strong>Logarithmic:</strong> Rises slowly at first, then accelerates upward. Creates dramatic, cinematic swells."],"ordered":false},{"type":"heading","text":"1.3 Hold Time (Hold)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> A time stage inserted between Attack and Decay where the sound stays locked at 100% peak level for a fixed time before starting to decay.","<strong>Sound Design Role:</strong> Essential for punchy synth kicks and snare bodies, keeping the attack at full impact for 10 to 30 milliseconds."],"ordered":false},{"type":"heading","text":"1.4 Decay Time (Decay / Dec)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The duration of time required for the envelope to drop from peak down to the <strong>Sustain Level</strong>.","<strong>The Sustain Rule:</strong> If Sustain is set to 100%, the Decay parameter has zero audible effect because the volume never drops.","<strong>Sound Design Roles:</strong>","<strong>30 ms to 150 ms (Fast Snappy Pluck):</strong> Tight house plucks, short 808 beater thuds, snappy clavs.","<strong>200 ms to 600 ms (Natural Acoustic Decay):</strong> Acoustic piano string dissipation, mallet xylophones.","<strong>Over 1.5 seconds (Long Tail):</strong> Large orchestral bells, gong strikes, decaying pads."],"ordered":false},{"type":"heading","text":"1.5 Decay Curve / Slope","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The curvature of the decay stage. Exponential curves provide the most natural, acoustic-feeling decay (like real piano strings and drumheads)."],"ordered":false},{"type":"heading","text":"1.6 Sustain Level (Sustain / Sust)","level":3},{"type":"list","items":["<strong>CRITICAL DISTINCTION:</strong> <strong>Sustain is NOT a time duration. Sustain is an AMPLITUDE LEVEL (dB / Percentage).</strong>","<strong>Technical Definition:</strong> The resting volume level held for as long as the MIDI key is physically pressed down.","<strong>Value Range:</strong> -inf dB to 0.0 dB (0% to 100%).","<strong>Sound Design Archetypes:</strong>","<strong>Sustain = 0%:</strong> The sound dies out completely even while holding the key. Essential for <strong>Plucks</strong>, <strong>Percussion</strong>, <strong>Pianos</strong>, and <strong>Stabs</strong>.","<strong>Sustain = 100%:</strong> The sound never drops in volume while held. Essential for <strong>Organs</strong>, <strong>Leads</strong>, and <strong>Sustained Beds</strong>.","<strong>Sustain = 50% to 80%:</strong> Initial punchy attack drops down to a comfortable sustained body (Brass, Strings, Synth Bass)."],"ordered":false},{"type":"heading","text":"1.7 Release Time (Release / Rel)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The duration of time required for the envelope to drop from the Sustain Level to complete silence after the key is released.","<strong>Sound Design Roles:</strong>","<strong>0 ms to 15 ms (Instant Cut):</strong> Basslines and rhythmic acid leads. Prevents low-end notes from overlapping.","<strong>100 ms to 300 ms (Natural Key Release):</strong> Natural acoustic instrument response.","<strong>1.0 s to 5.0 s (Lush Tail):</strong> Ambient pads, church organs, cinematic pianos."],"ordered":false}]},{"type":"step","title":"2. Multi-Stage & Advanced Envelope Parameters","blocks":[{"type":"heading","text":"2.1 DAHDSR Architecture","level":3},{"type":"list","items":["<strong>Stage Order:</strong> Delay -&gt; Attack -&gt; Hold -&gt; Decay -&gt; Sustain -&gt; Release.","<strong>Delay Stage:</strong> A programmable wait time before the Attack stage begins, useful for staggering layers in complex patches."],"ordered":false},{"type":"heading","text":"2.2 Velocity Sensitivity (Vel -> Level / Vel -> Attack)","level":3},{"type":"list","items":["<strong>Velocity -&gt; Level:</strong> Maps key strike hardness to volume (soft playing = quiet; hard hitting = full volume).","<strong>Velocity -&gt; Attack:</strong> Hitting keys harder accelerates the attack time, while soft playing creates a gentle swell."],"ordered":false},{"type":"heading","text":"2.3 Key Scaling (Time Tracking)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Automatically shortens Decay and Release times when playing higher notes on the keyboard, mimicking real acoustic instruments where higher strings decay much faster than low strings."],"ordered":false},{"type":"heading","text":"2.4 Envelope Loop Modes (Retrigger / Loop / Sync)","level":3},{"type":"list","items":["<strong>Loop Mode:</strong> Continuously loops the Attack and Decay stages while a key is held, acting like a custom rhythmic LFO.","<strong>One-Shot Mode (Trigger):</strong> Plays through the entire Attack, Decay, and Release cycle completely even on a fast key tap (mandatory for drum pads)."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-4-4-2","code":"4","title":"Comprehensive Parameter Encyclopedia — Volume 4: LFO & Modulation Parameters","blurb":"A Low-Frequency Oscillator (LFO) is a periodic or random control signal generator operating in the sub-audio frequency range (0.01 Hz to 50 Hz). This volume details every discrete parameter found in LFO blocks and Modulation Matrices, contr","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-04-lfo-modulation-parameters","title":"# Comprehensive Parameter Encyclopedia — Volume 4: LFO & Modulation Parameters","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"A <strong>Low-Frequency Oscillator (LFO)</strong> is a periodic or random control signal generator operating in the sub-audio frequency range (0.01 Hz to 50 Hz). This volume details every discrete parameter found in LFO blocks and Modulation Matrices, contrasting free-run versus synchronized clocks, polarities, smoothing slews, and matrix routing."}]},{"type":"step","title":"1. Primary LFO Parameters","blocks":[{"type":"heading","text":"1.1 LFO Rate / Frequency (Hz vs. Beat Sync)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The speed at which the LFO completes one full cycle.","<strong>Clock Modes:</strong>","<strong>Free-Running Hertz Mode (Hz):</strong>","Calibrated in cycles per second (0.01 Hz to 100.0 Hz).","Completely independent of the project BPM.","<em>Applications:</em> Natural acoustic vibrato (5.2 Hz), rotary speaker rotation (6.8 Hz), slow un-synced ambient drift (0.05 Hz).","<strong>Tempo-Synchronized Mode (Beat Sync):</strong>","Locks the LFO speed to the musical tempo grid (1/4, 1/8, 1/16, triplets, dotted)."],"ordered":false},{"type":"heading","text":"1.2 LFO Depth (Amount / Modulation Level)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Controls how far the target parameter is moved by the LFO.","<strong>Audible Effect:</strong> At 0%, no modulation occurs. Turning Depth up widens the sweep across the destination parameter."],"ordered":false},{"type":"heading","text":"1.3 LFO Waveform Topologies","level":3},{"type":"list","items":["<strong>Sine:</strong> Smooth, rounded, continuous sweeps (Vibrato, Auto-Pan).","<strong>Triangle:</strong> Straight linear rise and fall (Smooth wah-wah).","<strong>Saw Down:</strong> Instant top drop followed by a steady ramp up (Pumping sidechain).","<strong>Saw Up (Ramp):</strong> Steady build-up into a sudden drop (Tension risers).","<strong>Square:</strong> Binary alternating jumps between high and low (Rhythmic gating, trills).","<strong>Sample &amp; Hold (Random):</strong> Stepped random values on every clock tick (Retro computer blips).","<strong>Smooth Random:</strong> Interpolated, drifting random values (Analog circuit drift).","<strong>MSEG / Step Sequencer:</strong> Custom drawn multi-point vector curves (Complex wobbles and rhythmic patterns)."],"ordered":false},{"type":"heading","text":"1.4 Polarity: Bipolar vs. Unipolar","level":3},{"type":"list","items":["<strong>Bipolar Modulation (+/-):</strong> Swings symmetrically both above and below the parameter's resting position (ideal for Pitch Vibrato, Stereo Auto-Pan).","<strong>Unipolar Modulation (+):</strong> Swings in only one direction from the parameter's resting floor (ideal for Filter Cutoff sweeps)."],"ordered":false},{"type":"heading","text":"1.5 Phase Offset & Start Phase","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Sets where along the waveform cycle the LFO begins when triggered (0 degrees = start at zero rising, 90 degrees = start at maximum peak, 180 degrees = start at zero falling)."],"ordered":false},{"type":"heading","text":"1.6 Trigger & Playback Modes","level":3},{"type":"list","items":["<strong>Free-Run:</strong> The LFO cycles continuously in the background. Hitting a key catches the LFO wherever it happens to be.","<strong>Retrigger:</strong> Resets the LFO back to its starting phase every time a new note is played.","<strong>Poly LFO (Voice Mode):</strong> Calculates an independent LFO for every individual voice in a chord.","<strong>Scene / Mono LFO:</strong> Calculates one shared global LFO across all notes in the synth.","<strong>Legato Mode:</strong> Resets phase on staccato hits, but glides continuously during overlapping legato playing.","<strong>One-Shot Mode:</strong> Plays through one single cycle and stops (functioning like a simple envelope)."],"ordered":false},{"type":"heading","text":"1.7 Fade-In & Delay Time","level":3},{"type":"list","items":["<strong>Delay Time:</strong> How long the LFO waits before starting after a key is pressed.","<strong>Fade-In Time:</strong> How gradually the LFO depth swells from 0% to 100% (essential for natural vibrato that enters gently on held notes)."],"ordered":false},{"type":"heading","text":"1.8 Slew Rate / Smoothing","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Rounds off sharp edges on stepped waveforms (like Square or Sample &amp; Hold), preventing unwanted audio clicks."],"ordered":false}]},{"type":"step","title":"2. The Modulation Matrix Architecture","blocks":[{"type":"prose","html":"A <strong>Modulation Matrix</strong> connects modulation sources to synthesizer destinations:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ MODULATION SOURCE ] ---&gt; [ SCALE / VIA CONTROLLER ] ---&gt; [ TARGET DESTINATION ]\n    (e.g., LFO 1)                 (e.g., Mod Wheel)               (e.g., Filter Cutoff)</pre>"},{"type":"list","items":["<strong>Source:</strong> What is sending the control signal (LFO, Envelope, Velocity, Keytrack).","<strong>Destination:</strong> What parameter is being moved (Cutoff, Pitch, Warp, Volume, Pan).","<strong>Amount (Depth):</strong> How much the parameter moves.","<strong>Scale / Via:</strong> An auxiliary controller that scales the modulation depth (e.g., using the Mod Wheel to control how much Vibrato LFO reaches pitch).","<strong>Curve / Remap:</strong> Shapes the response curve (linear, exponential, or custom curve)."],"ordered":false}]},{"type":"step","title":"3. Cross-Modulation (Modulating Modulators)","blocks":[{"type":"prose","html":"Cross-modulation occurs when <strong>one modulator controls another modulator's parameters</strong>:"},{"type":"list","items":["Example: Routing a slow LFO 2 to modulate the speed (Rate) of LFO 1.","<em>Result:</em> LFO 1 continuously accelerates and decelerates, creating organic, evolving movement that never sounds stiff or repetitive."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-5-5-2","code":"5","title":"Comprehensive Parameter Encyclopedia — Volume 5: Voicing, Polyphony, Glide & Performance","blurb":"- Technical Definition: The maximum number of independent notes that can sound at the same time (typically 1 to 32 voices). - Settings:","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-05-voicing-performance-parameters","title":"# Comprehensive Parameter Encyclopedia — Volume 5: Voicing, Polyphony, Glide & Performance","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"<strong>Voicing &amp; Performance Architecture</strong> governs how a synthesizer allocates voice resources to incoming MIDI notes, manages polyphonic limits, executes pitch glides, and responds to physical performance controllers. This volume details every parameter in the voicing and performance domain."}]},{"type":"step","title":"1. Polyphony & Voice Allocation","blocks":[{"type":"heading","text":"1.1 Maximum Polyphony (Voices / Polyphony Limit)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The maximum number of independent notes that can sound at the same time (typically 1 to 32 voices).","<strong>Settings:</strong>","<strong>Mono (1 Voice):</strong> Essential for Basslines, 808s, and Solo Leads. Guarantees notes never overlap and create low-frequency mud.","<strong>Poly (4 to 8 Voices):</strong> Standard polyphonic keys, Rhodes, and chord stabs.","<strong>Poly (16 to 32 Voices):</strong> Long-release ambient pads and lush string arrangements."],"ordered":false},{"type":"heading","text":"1.2 Voice Stealing / Allocation Priority (Steal Mode)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> What the synthesizer does when you play a new note while all voice slots are already busy:","<strong>Oldest:</strong> Cuts off the note that has been playing the longest (standard for piano chords).","<strong>Lowest:</strong> Preserves high melody notes; steals the lowest-pitch voice.","<strong>Highest:</strong> Preserves bass notes; steals the highest-pitch voice.","<strong>Quietest:</strong> Steals the note with the lowest volume (usually in its late release tail), minimizing audible clicks.","<strong>Round-Robin:</strong> Cycles through voice slots sequentially."],"ordered":false}]},{"type":"step","title":"2. Voicing Modes: Mono, Poly, and Legato","blocks":[{"type":"heading","text":"2.1 Monophonic Mode (Mono)","level":3},{"type":"list","items":["<strong>Rule:</strong> Only one note plays at a time. Striking a new note instantly cuts off the previous note and triggers new envelope attacks on every hit."],"ordered":false},{"type":"heading","text":"2.2 Polyphonic Mode (Poly)","level":3},{"type":"list","items":["<strong>Rule:</strong> Multiple notes play at the same time up to the polyphony limit, with each note running its own independent envelopes and filters."],"ordered":false},{"type":"heading","text":"2.3 Legato Mode (Auto-Glide)","level":3},{"type":"list","items":["<strong>Rule:</strong> Monophonic mode that responds differently based on playing technique:","<strong>Staccato (Clean gap between notes):</strong> Envelopes retrigger on every note strike (new punchy attack).","<strong>Legato (Holding previous key while striking next key):</strong> Pitch glides smoothly to the new note while envelopes continue smoothly without retriggering.","<strong>Sound Design Role:</strong> Essential for expressive 808 slides, lead solos, and rolling drum &amp; bass lines."],"ordered":false}]},{"type":"step","title":"3. Portamento & Glide Parameters","blocks":[{"type":"heading","text":"3.1 Portamento / Glide Time (Glide / Time)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The duration of time required for the pitch to slide smoothly from one note to the next (typically 0 ms to 5.0 seconds).","<strong>Settings:</strong>","<strong>20 ms to 45 ms:</strong> Snappy, natural analog synth lead slide.","<strong>80 ms to 150 ms:</strong> Classic trap 808 sub-bass slides and octave jumps.","<strong>Over 500 ms:</strong> Dramatic sirens, dive bombs, and cinematic transitions."],"ordered":false},{"type":"heading","text":"3.2 Constant Time vs. Constant Rate","level":3},{"type":"list","items":["<strong>Constant Time:</strong> The pitch slide takes the <em>exact same amount of time</em> whether sliding 1 semitone or 3 octaves.","<strong>Constant Rate:</strong> The pitch moves at a fixed speed (semitones per second), so sliding 3 octaves takes much longer than sliding 1 semitone."],"ordered":false},{"type":"heading","text":"3.3 Glide Slope / Curve","level":3},{"type":"list","items":["<strong>Linear:</strong> Pitch moves at a constant rate (can sound unnatural across wide jumps).","<strong>Exponential / Logarithmic:</strong> Pitch moves in natural musical ratios, sounding smooth across multi-octave jumps."],"ordered":false}]},{"type":"step","title":"4. Performance & Pitch Controls","blocks":[{"type":"heading","text":"4.1 Pitch Bend Range (PB Up / PB Down)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Sets the maximum semitone range when moving the physical Pitch Bend wheel on your keyboard:","<strong>+/- 2 Semitones:</strong> Standard whole-step lead solos.","<strong>+/- 12 Semitones:</strong> Full-octave drops and EDM riser sweeps.","<strong>+/- 24 to +/- 48 Semitones:</strong> Multi-octave dive bombs and MPE finger glides."],"ordered":false},{"type":"heading","text":"4.2 Analog Drift / Slop / Circuit Instability","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Introduces subtle, random micro-variations into pitch, filter cutoff, and envelope times per voice, simulating the natural temperature drift and component tolerances of vintage analog hardware."],"ordered":false},{"type":"heading","text":"4.3 Direct Out Toggle (Sub-Bass Isolation)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Routes an oscillator directly to the master output, bypassing internal filters, distortion, and effects.","<strong>Sound Design Role:</strong> Keeps pure sine sub-bass clean, mono, and un-distorted while mid-range oscillators undergo heavy distortion and widening."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-6-6-2","code":"6","title":"Comprehensive Parameter Encyclopedia — Volume 6: Waveshaping, Distortion & Effects","blurb":"- Technical Definition: The pre-amplification gain level (0.0 dB to +36.0 dB) that pushes the audio signal into the distortion curve. - Acoustic Result: Higher drive pushes larger portions of the wave into saturation and clipping, generatin","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-06-waveshaper-distortion-fx-parameters","title":"# Comprehensive Parameter Encyclopedia — Volume 6: Waveshaping, Distortion & Effects","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"<strong>Waveshapers, Dynamic Processors, and Studio Effects</strong> shape harmonic density, dynamics, and spatial dimension. This volume details every parameter found in distortion, compression, spatial, and modulation processing units."}]},{"type":"step","title":"1. Waveshaping & Distortion Parameters","blocks":[{"type":"heading","text":"1.1 Drive / Input Gain","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The pre-amplification gain level (0.0 dB to +36.0 dB) that pushes the audio signal into the distortion curve.","<strong>Acoustic Result:</strong> Higher drive pushes larger portions of the wave into saturation and clipping, generating rich harmonic overtones and increasing perceived loudness and aggression."],"ordered":false},{"type":"heading","text":"1.2 Transfer Function Curves","level":3},{"type":"list","items":["<strong>Soft Clip (Tape / Tube):</strong> Smoothly rounds off waveform peaks. Generates warm odd harmonics with musical analog saturation.","<strong>Hard Clip (Digital):</strong> Cuts peaks flat with digital precision. Generates aggressive square-wave harmonics for harsh crunch.","<strong>Wave-Folding:</strong> Folds peaks back inward toward the center when they exceed the ceiling. Generates complex metallic overtones.","<strong>Asymmetrical (Tube Bias):</strong> Distorts positive peaks differently than negative peaks, generating rich even harmonics for classic analog tube warmth.","<strong>Bitcrush:</strong> Reduces digital bit-depth (e.g. 16-bit to 4-bit) for crunchy retro 8-bit grit.","<strong>Downsample:</strong> Reduces sampling rate, generating inharmonic digital aliasing."],"ordered":false},{"type":"heading","text":"1.3 Bias / Symmetry","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Shifts the waveform off-center before it hits the distortion stage, forcing it to clip asymmetrically and adding even tube harmonics."],"ordered":false}]},{"type":"step","title":"2. Dynamic Compression Parameters","blocks":[{"type":"heading","text":"2.1 Threshold (dBFS)","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The volume level above which the compressor starts turning down the signal. Audio below threshold passes untouched."],"ordered":false},{"type":"heading","text":"2.2 Ratio","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> How much the compressor turns down audio that exceeds the threshold:","<strong>2:1 to 4:1:</strong> Gentle, transparent leveling and bus glue.","<strong>8:1 to 20:1:</strong> Heavy transient control and punch enhancement.","<strong>Infinity:1 (Limiter):</strong> Hard ceiling preventing audio from exceeding threshold."],"ordered":false},{"type":"heading","text":"2.3 Attack Time as a Transient Shaper","level":3},{"type":"list","items":["<strong>Slow Attack (20 ms to 40 ms):</strong> Lets the initial transient click pass through uncompressed, making kicks, snares, and plucks much punchier.","<strong>Fast Attack (0.1 ms to 1 ms):</strong> Clamps down immediately, leveling peak spikes and smoothing transients."],"ordered":false},{"type":"heading","text":"2.4 Release Time as Body Enhancer","level":3},{"type":"list","items":["<strong>Fast Release (30 ms to 80 ms):</strong> Gain recovers quickly after the hit, pulling up quiet room reverb, subtle tails, and harmonic body.","<strong>Slow Release (300 ms to 1.0 s):</strong> Smooth, steady dynamic control without audible pumping."],"ordered":false},{"type":"heading","text":"2.5 Upward vs. Downward Compression (Multiband / OTT)","level":3},{"type":"list","items":["<strong>Downward Compression:</strong> Clamps loud peaks downward (reduces dynamic range from the top).","<strong>Upward Compression:</strong> Pulls quiet details upward (reduces dynamic range from the bottom).","<strong>OTT Multiband Processing:</strong> Combines both upward and downward compression across low, mid, and high bands, making sounds massive, dense, and full of presence."],"ordered":false}]},{"type":"step","title":"3. Spatial, Delay & Reverb Parameters","blocks":[{"type":"heading","text":"3.1 Delay Time (Milliseconds vs. Metric Sync)","level":3},{"type":"list","items":["<strong>Time Mode (ms):</strong> Free millisecond delay times. Setting delay to 10 to 30 ms with stereo offset creates Haas stereo widening.","<strong>Sync Mode:</strong> Locks delay repeats to musical tempo (1/4, 1/8 dotted, 1/16 triplet)."],"ordered":false},{"type":"heading","text":"3.2 Delay Feedback","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The amount of delayed sound fed back into the delay input to create repeats. High feedback produces long repeating echoes."],"ordered":false},{"type":"heading","text":"3.3 Reverb Size & Decay Time","level":3},{"type":"list","items":["<strong>Room Size:</strong> Sets the simulated room dimensions (from small booth to massive hall).","<strong>Decay Time:</strong> How long the reverberant tail takes to fade into silence."],"ordered":false},{"type":"heading","text":"3.4 Reverb Pre-Delay","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> The time gap between the dry sound hitting and the reverb tail starting.","<strong>Role:</strong> Setting pre-delay to 20 to 40 ms ensures the dry synth transient hits cleanly and punchily before the reverb wash appears behind it."],"ordered":false},{"type":"heading","text":"3.5 Reverb Low-Cut Filter","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> A high-pass filter (150 Hz to 350 Hz) on the reverb input.","<strong>THE LOW-CUT LAW:</strong> Mandatory on all synth design. Prevents sub-bass from entering the reverb and muddying the mix."],"ordered":false}]},{"type":"step","title":"4. Utility & Master Stage Parameters","blocks":[{"type":"heading","text":"4.1 Bass Mono Crossover Frequency","level":3},{"type":"list","items":["<strong>Technical Definition:</strong> Centers all audio below a specific frequency (120 Hz) into pure mono, while keeping midrange and high frequencies wide in stereo."],"ordered":false},{"type":"heading","text":"4.2 Stereo Width","level":3},{"type":"list","items":["<strong>0% (Mono):</strong> Sums audio to center.","<strong>100% (Normal Stereo):</strong> Unaltered stereo field.","<strong>Over 100%:</strong> Expands stereo width by boosting side channel energy."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-7-7-2","code":"7","title":"Comprehensive Parameter Encyclopedia — Volume 7: Engine-Specific Deep Parameter Maps","blurb":"This volume provides parameter-by-parameter maps for the core synthesizers in your studio: Ableton Operator, Surge XT, Vital, Ableton Drift, Ableton Analog, and Ableton's Physical Modeling Suite (Collision, Tension, Electric, Simpler). +---","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-07-engine-specific-deep-parameter-maps","title":"# Comprehensive Parameter Encyclopedia — Volume 7: Engine-Specific Deep Parameter Maps","blocks":[{"type":"step","title":"Scope & Architectural Definition","blocks":[{"type":"prose","html":"This volume provides parameter-by-parameter maps for the core synthesizers in your studio: <strong>Ableton Operator</strong>, <strong>Surge XT</strong>, <strong>Vital</strong>, <strong>Ableton Drift</strong>, <strong>Ableton Analog</strong>, and Ableton's Physical Modeling Suite (<strong>Collision</strong>, <strong>Tension</strong>, <strong>Electric</strong>, <strong>Simpler</strong>)."}]},{"type":"step","title":"1. Ableton Operator Deep Parameter Map","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                ABLETON OPERATOR PARAMETER MATRIX                                  |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| PARAMETER NAME      | VALUE RANGE           | ENGINE DOMAIN       | OPERATIONAL FUNCTION          |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Algorithm (1-11)**| 11 Discrete Diagrams  | Global Shell        | Sets FM cascade / additive    |\n|                     |                       |                     | routing between Oscs A,B,C,D. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Coarse Ratio**    | 0.5, 1, 2, ..., 20    | Oscillator (A-D)    | Harmonic frequency multiplier |\n|                     |                       |                     | relative to incoming MIDI key.|\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Fine Ratio**      | 0.000 - 0.999         | Oscillator (A-D)    | Decimal multiplier offset for |\n|                     |                       |                     | beating or inharmonicity.     |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Fixed Mode Freq** | 10 Hz - 20 kHz        | Oscillator (A-D)    | Locks oscillator in static Hz |\n|                     |                       |                     | independent of MIDI keys.     |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Osc Level**       | -inf to 0 dB          | Osc (A-D)           | Sets Carrier volume or        |\n|                     |                       |                     | Modulator FM index depth.     |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Feedback**        | 0% - 100%             | Osc D / Osc A       | Self-modulation loop: morphs  |\n|                     |                       |                     | sine -&gt; saw -&gt; white noise.   |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Additive Partials**| 16, 32, 64 Bins      | Central Display     | 64-partial harmonic bar graph |\n|                     |                       |                     | editor for drawing waveforms. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Env Loop Mode**   | Trigger / Loop / Sync | Central Display     | Converts envelope into cyclic |\n|                     |                       |                     | LFO or tempo-synced MSEG.     |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Global Tone**     | 0 - 100               | Global Shell        | Master high-frequency sideband|\n|                     |                       |                     | harmonic dampener.            |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Global Time**     | 0% - 1000%            | Global Shell        | Master multiplier scaling all |\n|                     |                       |                     | envelope durations in unison. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Pitch Env Amount**| -48 to +48 st         | Pitch Display       | Multi-octave transient pitch  |\n|                     |                       |                     | envelope assignable per osc.  |\n+---------------------+-----------------------+---------------------+-------------------------------+</pre>"}]},{"type":"step","title":"2. Surge XT Deep Parameter Map","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                   SURGE XT PARAMETER MATRIX                                       |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| PARAMETER NAME      | VALUE RANGE           | ENGINE DOMAIN       | OPERATIONAL FUNCTION          |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Scene Mode**      | Single, Dual, Split,  | Header Controls     | Sets dual-engine MIDI playback|\n|                     | Morph                 |                     | layering and keyboard zones.  |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Oscillator Type** | 12 Discrete Engines   | Oscillators 1, 2, 3 | Classic, Modern, Wavetable,   |\n|                     |                       |                     | Window, Sine, FM2, FM3, String|\n|                     |                       |                     | Twist, Alias, S&amp;H, Audio In.  |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Filter Topology** | Serial 1, Serial 2,   | Filter Matrix       | Sets signal routing across    |\n|                     | Parallel, Stereo, Ring|                     | Filter 1, Filter 2, &amp; Shaper. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Waveshaper Curve**| Soft, Hard, Asymmetric| Filter Matrix       | Non-linear wave-folding and   |\n|                     | Sine, Digital, Folder |                     | overdrive transfer functions. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Voice LFOs 1-6**  | 9 Waveform Engines    | Blue Modulation Bar | Polyphonic per-voice modulators|\n|                     |                       |                     | with StepSeq and MSEG tools.  |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Scene LFOs 1-6**  | 9 Waveform Engines    | Blue Modulation Bar | Monophonic global modulators  |\n|                     |                       |                     | shared across entire scene.   |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Airwindows FX**   | 20+ DSP Algorithms    | Effects Bus         | Studio-grade console and space|\n|                     |                       |                     | modeling inside synth engine. |\n+---------------------+-----------------------+---------------------+-------------------------------+</pre>"}]},{"type":"step","title":"3. Vital Deep Parameter Map","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                     VITAL PARAMETER MATRIX                                        |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| PARAMETER NAME      | VALUE RANGE           | ENGINE DOMAIN       | OPERATIONAL FUNCTION          |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Wave Frame**      | Frame 1 - 256         | Wavetable Osc 1-3   | Scans 3D wavetable position.  |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Spectral Warp**   | Formant, Stretch,     | Wavetable Osc 1-3   | Frequency-domain spectral     |\n|                     | Smear, Vocode, Sync   |                     | manipulation before filter.   |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Unison Voices**   | 1 - 16 Voices         | Wavetable Osc 1-3   | Stacks detuned unison voices. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Direct Out (D)**  | Toggle ON / OFF       | Osc 1, 2, 3, Sample | Bypasses filters and effects  |\n|                     |                       |                     | for clean mono sub routing.   |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Filter Blend**    | 0% - 100%             | Filter 1 &amp; Filter 2 | Continuous morph from Low-Pass|\n|                     |                       |                     | through Band-Pass to High-Pass|\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Multiband Comp**  | Low, Mid, High Bands  | Effects Rack        | OTT-style upward and downward |\n|                     |                       |                     | multiband dynamics compressor.|\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Matrix Remap**    | Vector Curve Canvas   | Matrix Tab          | Shapes custom non-linear      |\n|                     |                       |                     | modulation transfer curves.   |\n+---------------------+-----------------------+---------------------+-------------------------------+</pre>"}]},{"type":"step","title":"4. Ableton Drift Deep Parameter Map","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------+-----------------------+---------------------+-------------------------------+\n| PARAMETER NAME      | VALUE RANGE           | ENGINE DOMAIN       | OPERATIONAL FUNCTION          |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Osc 1 Shape**     | Sine, Tri, Saw, Pulse | Oscillator 1        | Continuous waveform morphing. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Osc 2 Sub / Oct** | Square / Triangle Sub | Oscillator 2        | Dedicated sub-octave generator|\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Drift Amount**    | 0% - 100%             | Global Performance  | Simulates discrete analog     |\n|                     |                       |                     | circuit component instability.|\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Filter Mode**     | 12 dB / 24 dB Saturate| Filter Stage        | Non-linear analog-modeled LP. |\n+---------------------+-----------------------+---------------------+-------------------------------+\n| **Stereo Mode**     | Mono, Stereo, Unison  | Voicing Section     | Multi-voice stereo spread.    |\n+---------------------+-----------------------+---------------------+-------------------------------+</pre>"}]},{"type":"step","title":"5. Physical Modeling Instruments Map","blocks":[{"type":"heading","text":"5.1 Ableton Collision","level":3},{"type":"list","items":["<strong>Mallet:</strong> Stiffness, Noise, Volume, Keytracking.","<strong>Resonator 1 &amp; 2:</strong> Beam, Plate, Membrane, Pipe, Tube.","<strong>Material / Inharmonics:</strong> Controls metal vs wood density and overtone decay damping."],"ordered":false},{"type":"heading","text":"5.2 Ableton Tension","level":3},{"type":"list","items":["<strong>Exciter:</strong> Bow (Friction/Speed), Hammer (Mass/Stiffness), Plectrum (Position/Protrusion).","<strong>String:</strong> Decay Damping, Inharmonic Tension, Finger Termination.","<strong>Body:</strong> Acoustic Soundboard Box Modeling (Guitar, Violin, Piano body size)."],"ordered":false},{"type":"heading","text":"5.3 Ableton Electric","level":3},{"type":"list","items":["<strong>Hammer:</strong> Hardness (Felt vs Rubber), Impact Velocity, Hit Noise.","<strong>Fork / Tine:</strong> Decay Length, High-Frequency Tone Bar Damping.","<strong>Pickup:</strong> Model (Rhodes vs Wurlitzer), Distance, Alignment Symmetry."],"ordered":false}]},{"type":"step","title":"6. Ableton Simpler & Drum Sampler Map","blocks":[{"type":"list","items":["<strong>Playback Modes:</strong> Classic (Polyphonic ADSR), 1-Shot (Gate vs Trigger), Slicing (Transient / Beat grid).","<strong>Warp Engines:</strong> Complex Pro (Preserves formants), Beats (Transient slice), Texture (Granular size/flux).","<strong>Drum Sampler:</strong> Zero-latency 1-shot percussion engine with integrated pitch envelopes, transient stretch, and pitch-tracked sub fundamental generation."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
